#!/usr/bin/env node
/**
 * Minimal stdio MCP server for Codex scenario smoke.
 * Tools: smoke_ping, smoke_echo
 *
 * Accepts Content-Length framed messages and NDJSON lines.
 */
const SERVER_INFO = { name: "eco-smoke-mcp", version: "1.0.0" };
const TOOLS = [
  {
    name: "smoke_ping",
    description: "Return a fixed smoke ping payload for Eco Codex scenario tests.",
    inputSchema: {
      type: "object",
      properties: {
        marker: { type: "string", description: "Optional marker to echo back" },
      },
      additionalProperties: false,
    },
  },
  {
    name: "smoke_echo",
    description: "Echo the provided text back for Eco Codex scenario tests.",
    inputSchema: {
      type: "object",
      properties: {
        text: { type: "string", description: "Text to echo" },
      },
      required: ["text"],
      additionalProperties: false,
    },
  },
];

/** Prefer Content-Length responses (MCP stdio transport). */
function writeMessage(message) {
  const body = JSON.stringify(message);
  process.stdout.write(`Content-Length: ${Buffer.byteLength(body, "utf8")}\r\n\r\n${body}`);
}

function ok(id, result) {
  writeMessage({ jsonrpc: "2.0", id, result });
}

function fail(id, code, message) {
  writeMessage({ jsonrpc: "2.0", id, error: { code, message } });
}

function handleRequest(msg) {
  if (!msg || typeof msg.method !== "string") return;
  const { id, method, params } = msg;
  if (method === "initialize") {
    ok(id, {
      protocolVersion: params?.protocolVersion ?? "2024-11-05",
      capabilities: { tools: { listChanged: false } },
      serverInfo: SERVER_INFO,
    });
    return;
  }
  if (method === "notifications/initialized" || method === "initialized") return;
  if (method === "tools/list") {
    ok(id, { tools: TOOLS });
    return;
  }
  if (method === "resources/list") {
    ok(id, { resources: [] });
    return;
  }
  if (method === "resources/templates/list") {
    ok(id, { resourceTemplates: [] });
    return;
  }
  if (method === "tools/call") {
    const name = params?.name;
    const args = params?.arguments ?? {};
    if (name === "smoke_ping") {
      const marker = typeof args.marker === "string" ? args.marker : "nop";
      ok(id, { content: [{ type: "text", text: `SMOKE_MCP_PONG:${marker}` }] });
      return;
    }
    if (name === "smoke_echo") {
      const text = typeof args.text === "string" ? args.text : "";
      ok(id, { content: [{ type: "text", text: `SMOKE_MCP_ECHO:${text}` }] });
      return;
    }
    fail(id, -32601, `Unknown tool: ${name}`);
    return;
  }
  if (method === "ping") {
    ok(id, {});
    return;
  }
  if (id !== undefined) fail(id, -32601, `Method not found: ${method}`);
}

let buffer = Buffer.alloc(0);

function tryConsumeFramed() {
  while (true) {
    const asText = buffer.toString("utf8");
    // Content-Length frame
    if (/^Content-Length:/i.test(asText) || asText.includes("Content-Length:")) {
      const headerEnd = buffer.indexOf("\r\n\r\n");
      if (headerEnd < 0) return;
      const header = buffer.subarray(0, headerEnd).toString("utf8");
      const match = /Content-Length:\s*(\d+)/i.exec(header);
      if (!match) {
        buffer = buffer.subarray(headerEnd + 4);
        continue;
      }
      const length = Number(match[1]);
      const bodyStart = headerEnd + 4;
      if (buffer.length < bodyStart + length) return;
      const body = buffer.subarray(bodyStart, bodyStart + length).toString("utf8");
      buffer = buffer.subarray(bodyStart + length);
      try {
        handleRequest(JSON.parse(body));
      } catch {
        // ignore
      }
      continue;
    }

    // NDJSON / bare JSON line
    const nl = buffer.indexOf(0x0a);
    if (nl < 0) return;
    const line = buffer.subarray(0, nl).toString("utf8").replace(/\r$/, "").trim();
    buffer = buffer.subarray(nl + 1);
    if (!line) continue;
    try {
      handleRequest(JSON.parse(line));
    } catch {
      // ignore
    }
  }
}

process.stdin.on("data", (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  tryConsumeFramed();
});
process.stdin.on("end", () => process.exit(0));
process.stdin.resume();
